public class Solution {
    public static String shipping(double total) {
        String cost = "unknown";
        if (total >= 100.0) {
            cost = "free";
        }
        if (total >= 50.0) {
            cost = "5.00";
        }
        if (total < 50.0) {
            cost = "8.00";
        }
        return cost;
    }
}
